  const dir = join(cache, LOD_KIT.kit.sha256.slice(0, 16), 'kit');
  const origin = (opts.origin ?? process.env.GRIPFORGE_LOD_KIT_URL ?? 'https://gripforge.ai/cli').replace(/\/$/, '');
