    const stage = join(cache, `.stage-${process.pid}`);
    await rm(stage, { recursive: true, force: true });
    await mkdir(stage, { recursive: true });
    await writeFile(join(stage, 'kit.tgz'), tgz);
    const tar = spawnSync('tar', ['-xzf', join(stage, 'kit.tgz'), '-C', stage], { encoding: 'utf8' });
    if (tar.status !== 0) throw Error(`The LOD kit could not be unpacked: ${tar.stderr || tar.error}`);
