/** sharp (the texture encoders) and basisu (KTX2) beside the kit: `npm install`, no install script runs. */
function installDeps(dir: string, log: (line: string) => void) {
  log('Installing the texture encoders (sharp, basisu) of the LOD kit…');
  const npm = process.platform === 'win32' ? 'npm.cmd' : 'npm';
  const r = spawnSync(npm, ['install', '--omit=dev', '--ignore-scripts', '--no-audit', '--no-fund', '--loglevel=error'], { cwd: dir, encoding: 'utf8', timeout: 600_000 });
  if (r.status !== 0) throw Error(`npm install failed in the LOD kit (${dir}): ${(r.stderr || r.error?.message || '').toString().slice(0, 400)}`);
}

/** Runs one request of the kit (docs: tools/lod-kit/lod-local.mjs). */
export function runKit<T = Record<string, unknown>>(kit: Kit, request: Record<string, unknown>, signal?: AbortSignal): Promise<T> {
  return new Promise((accept, reject) => {
    const child = spawn(process.execPath, [kit.entry], { stdio: ['pipe', 'pipe', 'pipe'], env: { ...process.env, ...(kit.bin ? { GRIPFORGE_LOD_BIN: kit.bin } : {}), ...(kit.collisionBin ? { GRIPFORGE_COLLISION_BIN: kit.collisionBin } : {}) }, signal });
    const out: Buffer[] = [], err: Buffer[] = [];
    child.stdout.on('data', (c) => out.push(c));
    child.stderr.on('data', (c) => { if (err.length < 64) err.push(c); });
    child.on('error', reject);
    child.on('close', () => {
      const text = Buffer.concat(out).toString('utf8');
      try {
        const answer = JSON.parse(text) as T & { ok?: boolean; error?: string };
        if (answer.ok === false) reject(Error(answer.error ?? 'The LOD kit failed'));
        else accept(answer);
      } catch { reject(Error(`The LOD kit gave no answer: ${(Buffer.concat(err).toString() || text).slice(0, 400)}`)); }
    });
    child.stdin.end(JSON.stringify(request));
  });
}

